package complete

import (
	"fmt"
	"time"

	"github.com/lallene/medcore-his/backend/internal/modules/ticketing"
)

// Support desk through ticketing.Service: creation by any staff member, triage, assignment,
// progress, waiting states, resolution, closure, reopening, cancellation, comments (public
// and internal), SLA deadlines (computed by the service from impact × urgency).
//
// Attachments are written by the HTTP handler to TICKET_UPLOAD_DIR (no service API): not
// generated by the seeder.

type supportPlanner struct{}

func (supportPlanner) Name() string         { return "Support" }
func (supportPlanner) Setup(w *World) error { return nil }

var ticketTopics = []struct {
	typ, cat, module, title, desc string
}{
	{"APPLICATION", "APPLICATION", "billing", "Impossible d'imprimer la facture", "Le bouton imprimer ne répond pas sur la fiche facture."},
	{"APPLICATION", "APPLICATION", "queue", "Patient introuvable dans la file", "Le patient enregistré n'apparaît pas dans la liste d'attente du triage."},
	{"ACCESS_REQUEST", "ACCESS", "access", "Accès au module laboratoire", "Demande d'accès en lecture aux résultats pour le service."},
	{"HARDWARE", "HARDWARE", "", "Imprimante de l'accueil en panne", "Bourrage papier récurrent sur l'imprimante d'étiquettes."},
	{"NETWORK", "NETWORK", "", "Wi-Fi instable au 2e étage", "Déconnexions fréquentes en hospitalisation."},
	{"INCIDENT", "APPLICATION", "pharmacy", "Stock affiché incorrect", "Le stock affiché ne correspond pas au comptage physique."},
	{"REQUEST", "OTHER", "", "Formation des nouveaux arrivants", "Organiser une session de prise en main de MedCore."},
	{"APPLICATION", "APPLICATION", "consultations", "Lenteur à l'ouverture du dossier", "Le dossier patient met plus de 10 secondes à s'afficher."},
	{"INCIDENT", "APPLICATION", "cash", "Écart de caisse non expliqué", "Écart constaté à la clôture, besoin d'analyse du journal."},
}

func (supportPlanner) PlanDay(w *World, d Day) {
	g := w.RNG.Stream("support.day", uint64(d.Index))
	n := volume(g, 2.4, w.Cfg, Day{Load: max(d.Load, 0.3)})
	for i := 0; i < n; i++ {
		at := d.At(8, 0).Add(g.Minutes(0, 10*60))
		gi := g.Stream("ticket", uint64(i))
		w.Sched.At(at, "support.ticket", func(ctx *StepContext) error { return supportTicket(ctx, gi) })
	}
}

func supportTicket(ctx *StepContext, g *RNG) error {
	w := ctx.W
	staff := w.Staff.With(func(m *Member) bool { return m.Role == "staff" && !m.Tags["inactive-profile"] && m.ProfileID != 0 })
	requester := staff[g.Intn(len(staff))]
	t := ticketTopics[g.Intn(len(ticketTopics))]
	impact := Pick(g, []string{"INDIVIDUAL", "INDIVIDUAL", "SERVICE", "DEPARTMENT", "FACILITY"})
	urgency := Pick(g, []string{"LOW", "MEDIUM", "MEDIUM", "HIGH", "CRITICAL"})
	det, err := w.Svc.Ticketing.Create(ticketing.CreateRequest{Type: t.typ, CategoryCode: t.cat, Title: t.title, Description: t.desc, Impact: impact, Urgency: urgency, ApplicationModule: t.module, PageURL: "/" + t.module}, requester.UserID)
	if err != nil {
		return err
	}
	id := det.ID
	var manager *Member
	for _, m := range w.Staff.ByFunction("SUPPORT_MANAGER") {
		manager = m
	}
	agents := w.Staff.ByFunction("SUPPORT_AGENT")
	if manager == nil || len(agents) == 0 {
		return nil
	}
	// Assignment does not grant visibility (product finding): an agent only sees tickets of
	// its primary service. Tickets of services without an agent are handled by the manager.
	agent := manager
	var local []*Member
	for _, a := range agents {
		if det.ServiceID != nil && w.Org.ServiceID(a.PrimaryService()) == *det.ServiceID {
			local = append(local, a)
		}
	}
	if len(local) > 0 {
		agent = local[g.Intn(len(local))]
	}
	ma, aa, ra := manager.TicketAccess(w), agent.TicketAccess(w), requester.TicketAccess(w)
	at := ctx.Sim
	next := func(minutes int) time.Time { at = at.Add(time.Duration(minutes) * time.Minute); return at }
	flow := func(name string, when time.Time, fn func() error) {
		w.Sched.At(when, name, func(ctx *StepContext) error { return fn() })
	}
	wf := func(a ticketing.Access, status, summary string) func() error {
		return func() error {
			_, err := w.Svc.Ticketing.Workflow(id, ticketing.WorkflowRequest{Status: status, ResolutionSummary: summary, ResolutionCode: map[bool]string{true: "FIXED", false: ""}[status == "RESOLVED"]}, a)
			return err
		}
	}
	comment := func(a ticketing.Access, content, vis string) func() error {
		return func() error {
			_, err := w.Svc.Ticketing.AddComment(id, ticketing.CommentRequest{Content: content, Visibility: vis}, a)
			return err
		}
	}
	// SLA: fast handling for most tickets, deliberate breaches for some.
	slow := g.Chance(0.2)
	first := g.Between(5, 120)
	if slow {
		first = g.Between(600, 3000)
	}
	switch r := g.Float(); {
	case r < 0.05: // cancelled by the requester
		flow("support.annulation", next(first), wf(ma, "CANCELLED", "Demande retirée par le demandeur"))
		return nil
	case r < 0.1: // stays NEW (recent tickets mostly)
		return nil
	}
	flow("support.triage", next(first), wf(ma, "TRIAGED", ""))
	if g.Chance(0.04) {
		return nil // triaged, waiting for an assignee
	}
	flow("support.affectation", next(g.Between(5, 60)), func() error {
		uid := agent.UserID
		_, err := w.Svc.Ticketing.Assign(id, ticketing.AssignRequest{UserID: &uid}, ma)
		return err
	})
	if g.Chance(0.04) {
		return nil // assigned, not yet started
	}
	flow("support.commentaire", next(g.Between(5, 90)), comment(aa, "Prise en charge, analyse en cours.", "PUBLIC"))
	flow("support.en-cours", next(g.Between(5, 120)), wf(aa, "IN_PROGRESS", ""))
	if g.Chance(0.04) {
		return nil // still being worked on
	}
	if g.Chance(0.3) {
		waiting := Pick(g, []string{"WAITING_USER", "WAITING_THIRD_PARTY"})
		flow("support.attente", next(g.Between(10, 240)), wf(aa, waiting, ""))
		if g.Chance(0.2) {
			return nil // still waiting for the user / the third party
		}
		flow("support.commentaire", next(g.Between(60, 1440)), comment(ra, "Informations complémentaires transmises.", "PUBLIC"))
		flow("support.reprise", next(g.Between(10, 240)), wf(aa, "IN_PROGRESS", ""))
	}
	if g.Chance(0.25) {
		flow("support.note-interne", next(g.Between(5, 120)), comment(aa, "Note interne : cause identifiée côté configuration.", "INTERNAL"))
	}
	resolveIn := g.Between(30, 480)
	if slow {
		resolveIn = g.Between(1500, 6000)
	}
	flow("support.resolution", next(resolveIn), wf(aa, "RESOLVED", "Problème corrigé et vérifié avec l'utilisateur"))
	switch r := g.Float(); {
	case r < 0.12: // reopened, then resolved again
		flow("support.reouverture", next(g.Between(60, 2880)), wf(ma, "REOPENED", ""))
		if g.Chance(0.3) {
			return nil // reopened, not yet taken back
		}
		flow("support.en-cours", next(g.Between(10, 240)), wf(aa, "IN_PROGRESS", ""))
		flow("support.resolution", next(g.Between(60, 600)), wf(aa, "RESOLVED", "Correctif complémentaire appliqué"))
		flow("support.cloture", next(g.Between(600, 4320)), wf(ma, "CLOSED", ""))
	case r < 0.75:
		flow("support.cloture", next(g.Between(600, 4320)), wf(ma, "CLOSED", ""))
	}
	return nil
}

var _ = fmt.Sprintf
